import json
leg = {'hip': 0.1, 'thigh': 0.8, 'calf': -1.5}
joints = {}
for j in app.actions.run('robot.joints')['joints']:
    side, part = j['name'].split('/')[-1].split('_')[:2]
    q = leg[part] * (-1.0 if part == 'hip' and side[1] == 'R' else 1.0)
    joints[j['name']] = q + (0.2 if part == 'thigh' and side[0] == 'R' else 0.0)
assert len(joints) == 12, joints
json.dump({'poses': [{'name': 'stand', 'joints': joints}]}, open(r'${out}/stand.json', 'w'))

s = ${s0}
print('STOPPED', s['state'], s['epoch'], s['observe'])
assert s['state'] == 'stopped' and s['observe'] is None, s
